// Stack — O(1) push/pop using array end
class Stack {
  #data = [];
  push(item)  { this.#data.push(item); }      // O(1) amortised
  pop()       { return this.#data.pop(); }     // O(1)
  peek()      { return this.#data.at(-1); }    // O(1)
  get size()  { return this.#data.length; }
  isEmpty()   { return this.#data.length === 0; }
}

// Queue — O(1) enqueue/dequeue using linked list
class QNode { constructor(v) { this.v = v; this.next = null; } }
class Queue {
  #head = null; #tail = null; #size = 0;

  enqueue(item) {                              // O(1)
    const n = new QNode(item);
    if (!this.#tail) { this.#head = this.#tail = n; }
    else { this.#tail.next = n; this.#tail = n; }
    this.#size++;
  }

  dequeue() {                                  // O(1)
    if (!this.#head) return undefined;
    const val = this.#head.v;
    this.#head = this.#head.next;
    if (!this.#head) this.#tail = null;
    this.#size--;
    return val;
  }

  peek()      { return this.#head?.v; }
  get size()  { return this.#size; }
  isEmpty()   { return this.#size === 0; }
}

// Classic stack application: balanced parentheses
function isBalanced(str) {
  const stack  = new Stack();
  const match  = { ')': '(', '}': '{', ']': '[' };
  for (const ch of str) {
    if ('({['.includes(ch)) stack.push(ch);
    else if (')}]'.includes(ch)) {
      if (stack.isEmpty() || stack.pop() !== match[ch]) return false;
    }
  }
  return stack.isEmpty();
}
console.log(isBalanced('({[]})')); // true
console.log(isBalanced('({[}])'));  // false

// BFS with Queue vs DFS with Stack
function bfs(graph, start) {
  const visited = new Set([start]);
  const queue   = [start];           // array as queue — OK for concept demo
  const order   = [];
  while (queue.length) {
    const node = queue.shift();      // NOTE: O(n) — use linked-list Queue in production
    order.push(node);
    for (const nb of (graph[node] ?? [])) {
      if (!visited.has(nb)) { visited.add(nb); queue.push(nb); }
    }
  }
  return order;
}

function dfs(graph, start) {
  const visited = new Set();
  const stack   = [start];
  const order   = [];
  while (stack.length) {
    const node = stack.pop();
    if (visited.has(node)) continue;
    visited.add(node); order.push(node);
    for (const nb of (graph[node] ?? [])) stack.push(nb);
  }
  return order;
}

const g = { A: ['B', 'C'], B: ['D'], C: ['D', 'E'], D: [], E: [] };
console.log('BFS:', bfs(g, 'A')); // ['A', 'B', 'C', 'D', 'E']
console.log('DFS:', dfs(g, 'A')); // ['A', 'C', 'E', 'D', 'B']
